package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", os.Args[1])
	if err != nil {
		panic(err)
	}
	defer db.Close()

	rows, err := db.Query("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
	if err != nil {
		panic(err)
	}
	var tables []string
	for rows.Next() {
		var n string
		rows.Scan(&n)
		tables = append(tables, n)
	}
	rows.Close()
	fmt.Println("TABLES:", tables)

	// collections
	crows, _ := db.Query("SELECT id, name, type, schema FROM collections")
	for crows.Next() {
		var id, name, typ, schema string
		crows.Scan(&id, &name, &typ, &schema)
		fmt.Printf("COLLECTION id=%s name=%s type=%s\n", id, name, typ)
		fmt.Printf("  schema=%s\n", schema)
	}
	crows.Close()

	// admins
	arows, _ := db.Query("SELECT id, email FROM admins")
	for arows.Next() {
		var id, email string
		arows.Scan(&id, &email)
		fmt.Printf("ADMIN id=%s email=%s\n", id, email)
	}
	arows.Close()
}
